local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local CanvasGroup = CS.UnityEngine.CanvasGroup

local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local UIFightTeamCommonConditionNode = "Game.UI.FightTeam.UIFightTeamDialog.UIFightTeamCommonConditionNode"

---@class UIFightTeamConditionNode
---@field CardPar                       	UnityEngine.RectTransform                            
local UIFightTeamConditionNode = Class("UIFightTeamConditionNode")
function UIFightTeamConditionNode:__init() 
    self._curLevelType = nil
end

function UIFightTeamConditionNode:__delete()
    self._curLevelType = nil
end

function UIFightTeamConditionNode:Awake()
end

function UIFightTeamConditionNode:Start()
end

function UIFightTeamConditionNode:Refresh(data, levelId, conditionData, conditionParas)
    if not data then
        return
    end
    if not conditionData or table.count(conditionData) <= 0 then
        KTool.SetActive(self.controller.gameObject, false)
        return
    end

    self:FillTitle(levelId)
    self:FillConditions(levelId, conditionData, conditionParas)
end

function UIFightTeamConditionNode:FillTitle(levelId)
    self._curLevelType = GoodsUtils.GetIdType(levelId, Constants.IDArea.Quests)     --关卡类型

    if self._curLevelType == Constants.IDType.QuestMaze then 
        CfUtils.FillText(self.TitleName, localize("胜利条件"))
    elseif self._curLevelType == Constants.IDType.QuestSeniorEquipCopy then 
        CfUtils.FillText(self.TitleName, localize("调查条件"))
    elseif self._curLevelType == Constants.IDType.QuestTrail then 
        CfUtils.FillText(self.TitleName, localize("限制条件"))
    elseif self._curLevelType == Constants.IDType.QuestTower then 
        CfUtils.FillText(self.TitleName, localize("Buff详情"))
    elseif self._curLevelType == Constants.IDType.QuestTalent then 
        CfUtils.FillText(self.TitleName, localize("难度提升"))   
    elseif self._curLevelType == Constants.IDType.QuestMain then 
        CfUtils.FillText(self.TitleName, localize("三星条件"))   
    elseif self._curLevelType == Constants.IDType.QuestNightCatTower then 
        CfUtils.FillText(self.TitleName, localize("Buff详情"))
    elseif self._curLevelType == Constants.IDType.QuestAdvancedTraining then
        CfUtils.FillText(self.TitleName, localize("上阵条件"))
    else
        CfUtils.FillText(self.TitleName, localize("三星条件"))
    end
end

--绘制条件
function UIFightTeamConditionNode:FillConditions(levelId, conditionData, conditionParas)
    if not conditionData then
        return
    end

    local count = 1
    for k, v in pairs(conditionData) do
        local go = self.FightConditions.transform:Find("cdt"..count)
        if not go then
            go = CfUtils.InstantiateGo(self.ConditionNode, self.FightConditions)
            go.name = "cdt"..count
        end

        local scr = CfUtils.GetLuaScr(go, UIFightTeamCommonConditionNode)
        local alphaNum = 1
        local isCompletCdt = QuestConfMgr:GetInstance():IsCompleteCondition(levelId, v.id, conditionParas)

        local type = GoodsUtils.GetIdType(levelId, Constants.IDArea.Quests)     --关卡类型
        if type == Constants.IDType.QuestMaze or type == Constants.IDType.QuestAdvancedTraining then
            isCompletCdt = false
        end

        alphaNum = (isCompletCdt and 1 or 0.3)

        if scr then
            scr:Refresh(v.desc, v.num)
            scr:FillAlphaNum(alphaNum)

            if self._curLevelType == Constants.IDType.QuestSeniorEquipCopy then 
                scr:SetTxtNumActive(true)
            else
                scr:SetImgHookActive(isCompletCdt)
            end
            KTool.SetActive(go, true)
        end
        count = count + 1
    end
end

function UIFightTeamConditionNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFightTeamConditionNode
